<?php $pageTitle='Settings';require_once dirname(__DIR__).'/includes/header.php';require_once dirname(__DIR__).'/includes/auth.php';require_auth(['super_admin']);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);foreach(['site_name','polling_interval','primary_color'] as $key){$pdo->prepare('INSERT INTO settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$key,trim($_POST[$key]??'')]);}audit_log($pdo,'update','settings',null,'Updated system settings');header('Location: settings.php?saved=1');exit;}$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM settings') as $r)$settings[$r['setting_key']]=$r['setting_value'];require dirname(__DIR__).'/includes/sidebar.php';?>
<section class="card" style="max-width:650px"><div class="eyebrow">System preferences</div><h2>Settings</h2><form method="post" class="grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div><label>Site Name</label><input name="site_name" value="<?=e($settings['site_name']??APP_NAME)?>"></div><div><label>Polling Interval (milliseconds)</label><input type="number" min="1000" name="polling_interval" value="<?=e($settings['polling_interval']??'3000')?>"></div><div><label>Primary Color</label><input type="color" name="primary_color" value="<?=e($settings['primary_color']??'#38bdf8')?>" style="height:50px"></div><button class="btn btn-primary">Save Settings</button></form></section>
